def asignar_posiciones(apps, schema_editor):
    """Conserva el orden actual de la tienda al activar la posición manual."""
    Product = apps.get_model("catalog", "Product")
    productos = list(Product.objects.order_by("-created_at", "-id"))
    for posicion, producto in enumerate(productos, start=1):
        producto.orden = posicion
    if productos:
        Product.objects.bulk_update(productos, ["orden"])


